/**
 * Seeds audit_checks if the table is empty.
 * Idempotent — uses INSERT OR IGNORE on check_number uniqueness.
 * @param {import('better-sqlite3').Database} db
 * @returns {number} rows inserted
 */
export function seedAuditChecks(db) {
  const existing = db.prepare('SELECT COUNT(*) AS cnt FROM audit_checks').get();
  if (existing.cnt > 0) return 0;

  const stmt = db.prepare(`
    INSERT OR IGNORE INTO audit_checks
      (check_number, name, category, severity_default, is_automated, logic_summary, seo_impact)
    VALUES
      (@check_number, @name, @category, @severity_default, @is_automated, @logic_summary, @seo_impact)
  `);

  const insertMany = db.transaction((checks) => {
    let inserted = 0;
    for (const c of checks) {
      const result = stmt.run({
        check_number:     c.check_number,
        name:             c.name,
        category:         c.category,
        severity_default: c.severity_default,
        is_automated:     c.is_automated,
        logic_summary:    c.logic_summary ?? '',
        seo_impact:       c.seo_impact    ?? '',
      });
      inserted += result.changes;
    }
    return inserted;
  });

  return insertMany(AUDIT_CHECKS);
}